def evaluate(expr: str) -> float:
    """
    Evaluates a mathematical expression string using a recursive descent parser approach.
    Supports +, -, *, / operators and respects standard operator precedence and parentheses.
    """

    def parse_expression(index):
        nonlocal pos
        value = parse_term(index)

        while pos < len(expr):
            if expr[pos] == '+':
                pos += 1
                value += parse_term(pos)
            elif expr[pos] == '-':
                pos += 1
                value -= parse_term(pos)
            else:
                break
        return value

    def parse_term(index):
        nonlocal pos
        value = parse_factor(index)

        while pos < len(expr):
            if expr[pos] == '*':
                pos += 1
                value *= parse_factor(pos)
            elif expr[pos] == '/':
                pos += 1
                value /= parse_factor(pos)
            else:
                break
        return value

    def parse_factor(index):
        nonlocal pos
        if expr[pos] == '(':
            pos += 1
            value = parse_expression(pos)
            pos += 1  # skip ')'
            return value
        return parse_number()

    def parse_number():
        nonlocal pos
        num_str = ''
        while pos < len(expr) and (expr[pos].isdigit() or expr[pos] == '.'):
            num_str += expr[pos]
            pos += 1
        return float(num_str)

    pos = 0
    result = parse_expression(pos)
    return result

class TokenType:
    NUMBER = "NUMBER"
    PLUS = "PLUS"
    MINUS = "MINUS"
    MULTIPLY = "MULTIPLY"
    DIVIDE = "DIVIDE"
    LPAREN = "LPAREN"
    RPAREN = "RPAREN"
    EOF = "EOF"


class Token:
    def __init__(self, type_, value=None):
        self.type = type_
        self.value = value


class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos]

    def error(self):
        raise Exception('Invalid character')

    def advance(self):
        self.pos += 1
        if self.pos > len(self.text) - 1:
            self.current_char = None
        else:
            self.current_char = self.text[self.pos]

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return Token(TokenType.NUMBER, float(result))

    def get_next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit() or self.current_char == '.':
                return self.number()
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.PLUS)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.MINUS)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MULTIPLY)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIVIDE)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)
            self.error()
        return Token(TokenType.EOF)


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.type == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.type == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result

    def term(self):
        result = self.factor()
        while self.current_token.type in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.factor()
            elif token.type == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


