class ExpressionEvaluator:
    def __init__(self, expr: str):
        self.expr = expr
        self.position = 0

    def parse_next_token(self):
        while self.position < len(self.expr) and self.expr[self.position] == ' ':
            self.position += 1
        if self.position >= len(self.expr):
            return None

        if self.expr[self.position] in '0123456789.':
            start = self.position
            while (self.position < len(self.expr) and 
                   (self.expr[self.position] in '0123456789.')):
                self.position += 1
            return float(self.expr[start:self.position])

        if self.expr[self.position] in "+-*/()":
            token = self.expr[self.position]
            self.position += 1
            return token

        raise ValueError("Invalid character in expression.")

    def parse_expression(self):
        value = self.parse_term()
        while True:
            token = self.parse_next_token()
            if token == '+':
                value += self.parse_term()
            elif token == '-':
                value -= self.parse_term()
            elif token is None:
                break
            else:
                raise ValueError("Unexpected token in expression.")
        return value

    def parse_term(self):
        value = self.parse_factor()
        while True:
            token = self.parse_next_token()
            if token == '*':
                value *= self.parse_factor()
            elif token == '/':
                divisor = self.parse_factor()
                if divisor == 0:
                    raise ValueError("Division by zero.")
                value /= divisor
            else:
                self.position -= len(token) if token else 0
                break
        return value

    def parse_factor(self):
        token = self.parse_next_token()
        if isinstance(token, float):
            return token
        elif token == '(':
            value = self.parse_expression()
            if self.parse_next_token() != ')':
                raise ValueError("Mismatched parentheses.")
            return value
        raise ValueError("Unexpected token in factor.")

