class Parser:
    def __init__(self, expr):
        self.expr = expr
        self.index = 0
        self.current_char = self.expr[self.index] if self.expr else None

    def error(self):
        raise ValueError("Invalid expression")

    def advance(self):
        self.index += 1
        if self.index < len(self.expr):
            self.current_char = self.expr[self.index]
        else:
            self.current_char = None

    def skip_whitespace(self):
        while self.current_char is not None and self.current_char.isspace():
            self.advance()

    def parse_number(self):
        result = ''
        while self.current_char is not None and (self.current_char.isdigit() or self.current_char == '.'):
            result += self.current_char
            self.advance()
        return float(result)

    def parse_parentheses(self):
        self.advance()  # Skip '('
        result = self.parse_expression()
        self.advance()  # Skip ')'
        return result

    def parse_factor(self):
        if self.current_char == '(':
            return self.parse_parentheses()
        elif self.current_char.isdigit() or self.current_char == '-':
            return self.parse_number()
        else:
            self.error()

    def parse_term(self):
        result = self.parse_factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.parse_factor()
            elif op == '/':
                result /= self.parse_factor()
        return result

    def parse_expression(self):
        result = self.parse_term()
        while self.current_char is not None and self.current_char in ('+', '-'):
            op = self.current_char
            self.advance()
            if op == '+':
                result += self.parse_term()
            elif op == '-':
                result -= self.parse_term()
        return result

