def tokenize(expression):
    tokens = []
    i = 0
    while i < len(expression):
        char = expression[i]
        if char.isdigit() or char == '.':
            num = ''
            while i < len(expression) and (expression[i].isdigit() or expression[i] == '.'):
                num += expression[i]
                i += 1
            tokens.append(Token('NUMBER', float(num)))
            continue
        elif char in '+-*/()':
            tokens.append(Token(char, char))
        i += 1
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def parse(self):
        return self.parse_expression()

    def parse_expression(self):
        node = self.parse_term()
        while self.pos < len(self.tokens) and self.tokens[self.pos].type_ in ('+', '-'):
            op = self.tokens[self.pos]
            self.pos += 1
            right = self.parse_term()
            node = (op.value, node, right)
        return node

    def parse_term(self):
        node = self.parse_factor()
        while self.pos < len(self.tokens) and self.tokens[self.pos].type_ in ('*', '/'):
            op = self.tokens[self.pos]
            self.pos += 1
            right = self.parse_factor()
            node = (op.value, node, right)
        return node

    def parse_factor(self):
        token = self.tokens[self.pos]
        if token.type_ == 'NUMBER':
            self.pos += 1
            return token.value
        elif token.type_ == '(':
            self.pos += 1
            node = self.parse_expression()
            self.pos += 1  # Skip the closing ')'
            return node

def evaluate(expr: str) -> float:
    """Evaluates arithmetic expressions with +, -, *, /, parentheses, and floating-point numbers using a recursive descent parser."""
    tokens = tokenize(expr)
    parser = Parser(tokens)
    ast = parser.parse()

    def evaluate_ast(node):
        if isinstance(node, float):
            return node
        op, left, right = node
        if op == '+':
            return evaluate_ast(left) + evaluate_ast(right)
        elif op == '-':
            return evaluate_ast(left) - evaluate_ast(right)
        elif op == '*':
            return evaluate_ast(left) * evaluate_ast(right)
        elif op == '/':
            return evaluate_ast(left) / evaluate_ast(right)

    return evaluate_ast(ast)
